package com.eidolon.sc.mobile;
import org.json.*;import java.util.*;
public class SocialRepairTests {
 static int n;interface Work{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}static void reject(Work w,String code)throws Exception{try{w.run();}catch(SocialReply.Invalid e){check(e.code.equals(code),"rejected safely: "+code);return;}throw new AssertionError("not rejected "+code);}
 public static void main(String[] args)throws Exception{
  String basic="{\"ja\":\"こんにちは {友達}\\\"\",\"zh\":\"你好\",\"placeId\":\"p\",\"likes\":[\"friend\",\"outsider\"],\"comments\":[]}";
  for(String value:new String[]{basic,"```json\n"+basic+"\n```","以下是动态：\n"+basic,"["+basic+"]","{\"post\":"+basic+"}","{\"moment\":"+basic+"}","{\"data\":"+basic+"}",JSONObject.quote(basic)}){JSONObject p=SocialData.post(value,Collections.singleton("friend"),Collections.singleton("p"));check(p.getString("zh").equals("你好")&&p.getJSONArray("likes").length()==1&&p.getString("placeId").equals("p"),"controlled wrapper compatibility and candidate validation "+n);}
  reject(()->SocialReply.object(""),"empty");reject(()->SocialReply.object("just text"),"not_json");reject(()->SocialReply.object("{\"ja\":\"未完"),"truncated");reject(()->SocialReply.object(basic+basic),"ambiguous");reject(()->SocialReply.object("["+basic+","+basic+"]"),"array_count");reject(()->SocialReply.object("{\"post\":"+basic+",\"data\":"+basic+"}"),"ambiguous");
  reject(()->SocialData.pair(new JSONObject().put("ja","こんにちは")),"missing_zh");reject(()->SocialData.pair(new JSONObject().put("ja",5).put("zh","中文")),"missing_ja");
  JSONObject pair=SocialData.pair(new JSONObject().put("ja","<ja>こんにちは</ja>").put("zh","</ja><zh>中文</zh>"));check(pair.getString("ja").equals("こんにちは")&&pair.getString("zh").equals("中文"),"language wrappers do not leak into moments");
  JSONObject local=SocialFailure.classify(new JSONException("No value for lat"),false,"prepare_places"),remote=SocialFailure.classify(new JSONException("private raw response must not escape"),false,"parse");check(local.getString("category").equals("local_data")&&!local.getBoolean("requestAttempted")&&local.getString("field").equals("lat"),"pre-request JSON failure is not mislabelled model output");check(remote.getString("category").equals("format")&&remote.getBoolean("requestAttempted")&&!remote.toString().contains("private raw"),"response JSON failure classified without exposing provider body");
  JSONObject old=new JSONObject().put("category","format").put("stage","prepare").put("exception","JSONException");check(SocialFailure.provenUnsent(old),"only proven old local JSON failures can receive quota credit");check(!SocialFailure.provenUnsent(new JSONObject().put("category","format").put("stage","parse")),"actual model-return format failure still consumes request quota");check(!SocialFailure.provenUnsent(new JSONObject().put("requestAttempted",JSONObject.NULL)),"null request status is not proof for quota refund");
  check(!SocialFailure.provenUnsent(new JSONObject()),"unknown old failures receive no speculative refund");
  JSONObject task=new JSONObject().put("diagnostic",old).put("error","模型返回不是完整的动态JSON结构");String saved=task.toString();JSONObject shown=SocialFailure.present(task);check(task.toString().equals(saved)&&shown.getJSONObject("diagnostic").getString("category").equals("local_data")&&shown.getString("error").contains("旧记录"),"legacy diagnostic adapts for reading without rewriting task history");
  reject(()->SocialReply.object(JSONObject.quote(basic)+" another object"),"ambiguous");
  check(SocialFailure.classify(new ModelClient.ServiceException(429),false,"request").getInt("httpStatus")==429,"service limit is separate from JSON or configuration");
  JSONObject generic=new JSONObject().put("error","生成未完成，未自动重发；请检查模型配置或稍后明确重试");check(SocialFailure.present(generic).getString("error").contains("不能据此认定")&&!SocialFailure.present(generic).has("diagnostic")&&generic.getString("error").startsWith("生成未完成"),"old generic failure stays unknown without fabricated diagnostics or record rewrite");
  JSONObject oldBackup=SocialRulesTests.root(1793751600000L);oldBackup.getJSONObject("social").getJSONArray("posts").getJSONObject(0).put("zh","こんにちは");String originalBackup=oldBackup.toString();SocialBackup.validate(oldBackup,Collections.singleton("mano"));check(oldBackup.toString().equals(originalBackup),"legacy backup validation retains old text and does not apply new-response normalization");
  System.out.println("Social repair checks "+n);
 }
}
